// src/context/auth-context.tsx
"use client";

import { createContext, ReactNode, useCallback, useContext, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { storage } from "lib/storage";
import { authService } from "services/auth.service";
import { User } from "types";
import { LoginValues, SignupValues } from "validations/auth";

interface AuthContextValue {
  user: User | null;
  isLoading: boolean;
  login: (input: LoginValues) => Promise<User>;
  signup: (input: Pick<SignupValues, "name" | "email" | "password">) => Promise<User>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const router = useRouter();
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // পেজ রিফ্রেশ করলেও login থাকবে
  useEffect(() => {
    const token = storage.getToken();
    const savedUser = storage.getUser();
    if (token && savedUser) {
      setUser(savedUser);
    }
    setIsLoading(false);
  }, []);

  const login = useCallback(async (input: LoginValues) => {
    const { user, token } = await authService.login(input);
    storage.setSession(token, user);
    setUser(user);
    return user;
  }, []);

  const signup = useCallback(
    async (input: Pick<SignupValues, "name" | "email" | "password">) => {
      const { user, token } = await authService.signup(input);
      storage.setSession(token, user);
      setUser(user);
      return user;
    },
    []
  );

  const logout = useCallback(() => {
    storage.clear();
    setUser(null);
    router.replace("/login");
  }, [router]);

  const value = useMemo(
    () => ({ user, isLoading, login, signup, logout }),
    [user, isLoading, login, signup, logout]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used inside <AuthProvider>");
  }
  return context;
}